import re
def render_prompt(template, variables):
    missing = set()
    def repl(m):
        if m.group(0) == "\\{{":
            return "{{"
        name = m.group(1)
        if name in variables:
            return str(variables[name]).replace("{{", "{ {").replace("}}", "} }")
        missing.add(name)
        return m.group(0)
    out = re.sub(r"\\\{\{|\{\{\s*([A-Za-z_][A-Za-z0-9_]*)\s*\}\}", repl, template)
    return [out, sorted(missing)]

