def rrf(rankings, k):
    scores = {}
    for ranking in rankings:
        for rank, doc in enumerate(ranking, 1):
            scores[doc] = scores.get(doc, 0.0) + 1.0 / (k + rank)
    return [[d, s] for d, s in sorted(scores.items(), key=lambda t: (-t[1], t[0]))]

