aie-near-dedup.solution:
import re
def dedup(texts, n, threshold):
    def shingles(t):
        toks = re.findall(r"[a-z0-9]+", t.lower())
        if not toks:
            return frozenset()
        if len(toks) < n:
            return frozenset([tuple(toks)])
        return frozenset(tuple(toks[i:i + n]) for i in range(len(toks) - n + 1))
    kept, kept_sets = [], []
    for i, t in enumerate(texts):
        s = shingles(t)
        dup = False
        for k in kept_sets:
            union = len(s | k)
            j = 1.0 if union == 0 else len(s & k) / union
            if j >= threshold:
                dup = True
                break
        if not dup:
            kept.append(i)
            kept_sets.append(s)
    return kept

